code.source:
#include <stdio.h>

int main() {
    int x = 6;
    printf("without brackets: %d\n", x & 1 == 0);
    printf("with brackets   : %d\n", (x & 1) == 0);
    return 0;
}

#include <stdio.h>

int main() {
    int marks = 72;
    int age = 16;

    char result = (marks >= 40) ? 'P' : 'F';
    printf("Result: %c\n", result);

    printf("Bus fare: %d rupees\n", (age < 12) ? 10 : 20);
    return 0;
}

